# -*- coding: utf-8 -*-
import nbformat as nbf
from nb_common import HEADER_RULE, SETUP_CODE, DECLARACAO_IA
REFS_MH = "Mantel, N., & Haenszel, W. (1959). Statistical aspects of the analysis of data from retrospective studies of disease. *Journal of the National Cancer Institute, 22*(4), 719–748.\n\nRoberts, D. R., et al. (2017). Cross-validation strategies for data with temporal, spatial, hierarchical, or phylogenetic structure. *Ecography, 40*(8), 913–929. https://doi.org/10.1111/ecog.02881"
def monta(nome, titulo, intro, partes, refs):
    cells = []; md = lambda s: cells.append(nbf.v4.new_markdown_cell(s)); code = lambda s: cells.append(nbf.v4.new_code_cell(s))
    md(f"# {titulo}\n\n{HEADER_RULE}\n\n{intro}"); code(SETUP_CODE); code(open("nb27_base.py").read().replace('log_ia("27.0', f'log_ia("{nome[:2]}.0'))
    for p_ in partes: code(p_)
    md(f"---\n## Referências\n\n{refs}\n\n{DECLARACAO_IA}")
    nb = nbf.v4.new_notebook(); nb["cells"] = cells; nb["metadata"] = {"kernelspec": {"name": "python3", "display_name": "Python 3"}, "language_info": {"name": "python"}, "colab": {"name": f"{nome}.ipynb"}}
    nbf.write(nb, f"{nome}.ipynb"); print("ok", nome)
monta("29_fatores_dentro_das_malhas", "29 · Fatores da via dentro das malhas: o que serve de parâmetro do EAR",
      "**Por que este passo.** A Declaração de Rede traz, por trecho, bitola, velocidade, rampa, carga por eixo, tráfego vinculado, dormente, trilho, fixação, taxa de dormentação, sinalização, produto perigoso e número de linhas; um EAR de ferrovia nova conhece esses valores no projeto. Este notebook separa o que muda o risco dentro de uma ferrovia (candidato a parâmetro do EAR) do que só distingue uma ferrovia da outra, com classes e regra de decisão declaradas antes, risco relativo de Mantel-Haenszel estratificado por malha, faixa de pátio e classe de raio, ganho em trechos inteiros fora do ajuste (30 sorteios) e placebo.\n\n**Gates, declarados antes do código:** 20.936 células; 2.123 km atingidos; regra FICO 0,588; classe de referência com risco relativo 1; classes somam 20.936; placebo com ganho de no máximo 0,01. O placebo falhou na primeira execução (0,016) e a especificação recebeu o efeito fixo da malha (registrado no código).",
      [open("nb29_fatores.py").read() + '\nexportar_registros("29")', open("nb29_fig.py").read()], REFS_MH)
monta("30_ear_v3_ferrovia_nova", "30 · EAR v3 em multiplicadores de risco e teste como ferrovia nova",
      "**Por que este passo.** Transforma as faixas aferidas (notebook 27) e os fatores aprovados (notebook 29) numa tabela de multiplicadores que um EAR pode replicar, e testa a tabela como se cada malha fosse uma ferrovia nova (malha inteira fora do ajuste). Inclui a aplicação à Norte-Sul, ajustada sem ela, contra as faixas do EAR da FNS.\n\n**Gates, declarados antes do código:** logística com atributos, malha fora, 0,633 e regra FICO 0,589 (notebook 24); rótulos embaralhados entre 0,45 e 0,55; multiplicador de referência 1; classes do mapa somam 100% da extensão.",
      [open("nb30_ear_v3.py").read() + '\nexportar_registros("30")'], REFS_MH)
monta("31_monte_carlo_posicao", "31 · Monte Carlo da incerteza de posição dos acidentes e dos pátios",
      "**Por que este passo.** O RAAF localiza o acidente pelo km e a posição do AMV é estimada pelas pontas do pátio. Este notebook propaga esses erros por simulação de Monte Carlo (cinco cenários declarados antes, 200 réplicas cada) e mede se os limites aferidos, o excesso de risco e o ganho sobre a FICO se mantêm. A figura final junta o teste de ferrovia nova (notebook 30) e o Monte Carlo.\n\n**Gates, declarados antes do código:** réplica sem erro reproduz a célula de todos os eventos e os 2.123 km atingidos; regra FICO dentro das malhas 0,589; deslocamento zero reproduz a distância ao pátio; 2.681 eventos. A primeira execução falhou no primeiro gate (73 eventos com km fora da célula atribuída) e a especificação passou a sortear o erro em torno da posição dentro da célula atribuída (registrado no código).",
      [open("nb31_monte_carlo.py").read() + '\nexportar_registros("31")', open("nb30_fig.py").read()], "Metropolis, N., & Ulam, S. (1949). The Monte Carlo method. *Journal of the American Statistical Association, 44*(247), 335–341. https://doi.org/10.1080/01621459.1949.10483310\n\n" + REFS_MH)
